function(props) {
  // Main component function
  function BrowserTaskDetailCard(props) {
    const data = props.data;
    if (!data) return null;

    // Handle both single task and list of tasks
    const tasks = Array.isArray(data) ? data : (Array.isArray(data.data) ? data.data : [data.data]);

    // Function to get status description
    function getStatusDescription(status) {
      const statusDescriptions = {
        'created': 'Task has been created but not started yet',
        'running': 'Task is currently running',
        'finished': 'Task has completed successfully',
        'stopped': 'Task was manually stopped',
        'paused': 'Task is temporarily paused',
        'failed': 'Task encountered an error and failed'
      };
      return statusDescriptions[status] || 'Unknown status';
    }

    // Format date function
    function formatDate(dateString) {
      if (!dateString) return '';
      const date = new Date(dateString);
      if (date.toString() === 'Invalid Date') return '';

      const now = new Date();
      const diffMs = now - date;
      const diffMins = Math.floor(diffMs / 60000);
      const diffHours = Math.floor(diffMins / 60);
      const diffDays = Math.floor(diffHours / 24);

      if (diffMins < 1) return 'Just now';
      if (diffMins < 60) return `${diffMins}m ago`;
      if (diffHours < 24) return `${diffHours}h ago`;
      if (diffDays < 7) return `${diffDays}d ago`;

      return date.toLocaleDateString('en-US', {
        month: 'short',
        day: 'numeric'
      });
    }

    // External link button component
    function ExternalLinkButton({ url }) {
      if (!url) return null;

      const buttonStyle = {
        display: 'inline-flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: '6px 12px',
        backgroundColor: '#f8fafc',
        border: '1px solid #e2e8f0',
        borderRadius: '4px',
        color: '#64748b',
        fontSize: '12px',
        fontWeight: '500',
        textDecoration: 'none',
        cursor: 'pointer',
        transition: 'background-color 0.2s'
      };

      return React.createElement('a', {
        href: url,
        target: '_blank',
        rel: 'noopener noreferrer',
        style: buttonStyle,
        onMouseOver: (e) => {
          e.currentTarget.style.backgroundColor = '#f1f5f9';
        },
        onMouseOut: (e) => {
          e.currentTarget.style.backgroundColor = '#f8fafc';
        }
      }, 'View Live');
    }

    // Status with tooltip
    function StatusWithTooltip({ status }) {
      const description = getStatusDescription(status);

      const containerStyle = {
        position: 'relative',
        cursor: 'pointer',
        display: 'inline'
      };

      return React.createElement('span', { 
        style: containerStyle,
        onMouseOver: function(e) {
          const tooltip = document.createElement('div');
          tooltip.className = 'status-tooltip';
          tooltip.style.position = 'absolute';
          tooltip.style.bottom = '100%';
          tooltip.style.left = '0';
          tooltip.style.marginBottom = '6px';
          tooltip.style.padding = '4px 8px';
          tooltip.style.backgroundColor = '#333';
          tooltip.style.color = 'white';
          tooltip.style.borderRadius = '4px';
          tooltip.style.fontSize = '10px';
          tooltip.style.whiteSpace = 'nowrap';
          tooltip.style.zIndex = '10';
          tooltip.textContent = description;

          // Add arrow
          const arrow = document.createElement('div');
          arrow.style.position = 'absolute';
          arrow.style.top = '100%';
          arrow.style.left = '8px';
          arrow.style.borderWidth = '4px';
          arrow.style.borderStyle = 'solid';
          arrow.style.borderColor = '#333 transparent transparent transparent';
          tooltip.appendChild(arrow);

          e.currentTarget.appendChild(tooltip);
        },
        onMouseOut: function(e) {
          const tooltip = e.currentTarget.querySelector('.status-tooltip');
          if (tooltip) {
            tooltip.remove();
          }
        }
      }, status);
    }

    // Link icon component
