        fill: 'none',
        style: { color: '#64748b' }
      }, [
        React.createElement('path', {
          key: 'p1',
          d: 'M6.5 9.5L9.5 6.5',
          stroke: 'currentColor',
          strokeWidth: '1.5',
          strokeLinecap: 'round',
          strokeLinejoin: 'round'
        }),
        React.createElement('path', {
          key: 'p2',
          d: 'M4.5 7.5L3 9C2.17157 9.82843 2.17157 11.1716 3 12C3.82843 12.8284 5.17157 12.8284 6 12L7.5 10.5',
          stroke: 'currentColor',
          strokeWidth: '1.5',
          strokeLinecap: 'round',
          strokeLinejoin: 'round'
        }),
        React.createElement('path', {
          key: 'p3',
          d: 'M8.5 5.5L10 4C10.8284 3.17157 12.1716 3.17157 13 4C13.8284 4.82843 13.8284 6.17157 13 7L11.5 8.5',
          stroke: 'currentColor',
          strokeWidth: '1.5',
          strokeLinecap: 'round',
          strokeLinejoin: 'round'
        })
      ]);
    }

    // Card styles
    const cardStyle = {
      position: 'relative',
      borderRadius: '8px',
      border: '1px solid #e2e8f0',
      backgroundColor: '#ffffff',
      padding: '12px 16px',
      marginBottom: '12px',
      width: '100%',
      boxSizing: 'border-box'
    };

    const flexContainerStyle = {
      display: 'flex',
      alignItems: 'flex-start',
      justifyContent: 'space-between',
      gap: '8px'
    };

    const contentStyle = {
      minWidth: 0,
      flex: 1
    };

    const titleContainerStyle = {
      display: 'flex',
      alignItems: 'center',
      gap: '4px'
    };

    const titleStyle = {
      fontWeight: '500',
      color: '#1e293b',
      overflow: 'hidden',
