      gap: '12px',
      width: '100%'
    };

    // Render a single task card
    function renderTaskCard(task) {
      if (!task) return null;

      // For get_task_status endpoint, the data might just be a string
      if (typeof task === 'string') {
        return React.createElement('div', { style: cardStyle },
          React.createElement('div', { style: flexContainerStyle },
            React.createElement('div', { style: contentStyle },
              React.createElement('h3', { style: titleStyle }, 'Task Status'),
              React.createElement('p', { style: subtitleStyle },
                React.createElement(StatusWithTooltip, { status: task })
              )
            )
          )
        );
      }

      // Extract task details
      const taskId = task.id || '';
      const taskDescription = task.task || 'Browser Task';
      const status = task.status || 'created';
      const createdAt = formatDate(task.created_at);
      const liveUrl = task.live_url || '';

      return React.createElement('div', { style: cardStyle },
        React.createElement('div', { style: flexContainerStyle },
          React.createElement('div', { style: contentStyle },
            React.createElement('div', { style: titleContainerStyle },
              liveUrl && React.createElement('a', {
                href: liveUrl,
                target: '_blank',
                rel: 'noopener noreferrer',
                style: linkStyle
              }, React.createElement(LinkIcon)),
              React.createElement('h3', { style: titleStyle }, taskDescription)
