        tasks.map((task, index) => React.createElement('div', { key: index }, renderTaskCard(task)))
      );
    } else if (tasks.length === 1) {
      return renderTaskCard(tasks[0]);
    } else {
      return null;
    }
  }

  return BrowserTaskDetailCard(props);
}
